// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address adminAddr1, address adminAddr2, bool access) public {
        vm.assume(adminAddr1 != address(0) && adminAddr2 != address(0));

        // Call adjustAdminAccess to set adminAddr1 as admin
        c.adjustAdminAccess(adminAddr1, true);

        // Now call adjustAdminAccess again with different parameters
        c.adjustAdminAccess(adminAddr2, access);

        // Create test arrays for balanceOfBatch
        address[] memory accounts = new address[](2);
        accounts[0] = address(0x1);
        accounts[1] = address(0x2);

        uint256[] memory ids = new uint256[](2);
        ids[0] = 0;
        ids[1] = 1;

        // The rule: balanceOfBatch should return an array of the same length as input
        // and for each i, the returned balance should equal balanceOf(accounts[i], ids[i])
        uint256[] memory balances = c.balanceOfBatch(accounts, ids);

        bool lengthsMatch = (balances.length == accounts.length);
        bool balancesMatch = (balances.length == 2 && 
                              balances[0] == c.balanceOf(accounts[0], ids[0]) && 
                              balances[1] == c.balanceOf(accounts[1], ids[1]));

        assertTrue(lengthsMatch && balancesMatch);
    }
}

